69	    private String householdId;
70	
71	    @Column(name = "namesake_count")
72	    private Integer namesakeCount;
73	
74	    @Column(name = "household_size")
75	    private Integer householdSize;
76	
77	    @Column(name = "possible_duplicate")
78	    private Boolean possibleDuplicate;
79	
80	    @Column(name = "possible_duplicate_of")
81	    private Integer possibleDuplicateOf;
82	
83	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
84	    private Set<Pet> pets;
85	
86	    public String getAddress() {
87	        return this.address;
88	    }
89	
90	    public void setAddress(String address) {
91	        this.address = address;
92	    }
93	
94	    public String getCity() {
95	        return this.city;
96	    }
97	
98	    public void setCity(String city) {
99	        this.city = city;
100	    }
101	
102	    public String getTelephone() {
103	        return this.telephone;
104	    }
105	
106	    public void setTelephone(String telephone) {
107	        this.telephone = telephone;
108	    }
109	
110	    /**
111	     * The owner's stored E.164 {@link #getTelephone() telephone} formatted for humans: the country
112	     * code, a space, then the national digits grouped in threes (e.g. {@code "+61 412 345 678"}).
113	     * The raw {@link #getTelephone() telephone} stays in E.164 form. Absent until a telephone has
114	     * been set.
115	     */
116	    public String getTelephoneDisplay() {
117	        return Telephone.forDisplay(this.telephone);
118	    }
119	
120	    public String getEmail() {
121	        return this.email;
122	    }
