152	    public String getCustomerCode() {
153	        return this.customerCode;
154	    }
155	
156	    public void setCustomerCode(String customerCode) {
157	        this.customerCode = customerCode;
158	    }
159	
160	    public String getHouseholdId() {
161	        return this.householdId;
162	    }
163	
164	    public void setHouseholdId(String householdId) {
165	        this.householdId = householdId;
166	    }
167	
168	    public Integer getNamesakeCount() {
169	        return this.namesakeCount;
170	    }
171	
172	    public void setNamesakeCount(Integer namesakeCount) {
173	        this.namesakeCount = namesakeCount;
174	    }
175	
176	    public Integer getHouseholdSize() {
177	        return this.householdSize;
178	    }
179	
180	    public void setHouseholdSize(Integer householdSize) {
181	        this.householdSize = householdSize;
182	    }
183	
184	    /**
185	     * Whether this owner, though not a hard duplicate, shares an existing owner's last name and
186	     * postcode while holding a different telephone. Resolved at creation and stored so it is
187	     * reported consistently on every later read.
188	     */
189	    public Boolean getPossibleDuplicate() {
190	        return this.possibleDuplicate;
191	    }
192	
193	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
194	        this.possibleDuplicate = possibleDuplicate;
195	    }
196	
197	    /**
198	     * The id of the existing owner this owner is a possible duplicate of, or {@code null} when it
199	     * is not a possible duplicate.
200	     */
201	    public Integer getPossibleDuplicateOf() {
202	        return this.possibleDuplicateOf;
203	    }
204	
205	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
206	        this.possibleDuplicateOf = possibleDuplicateOf;
207	    }
208	
209	    /**
210	     * The owner's identity key: the single derived value used to detect duplicate owners, formed
211	     * as {@code normalizedTelephone + '|' + email + '|' + householdId} where an absent telephone,
212	     * email or household contributes an empty string. Two owners are duplicates only when their
213	     * whole identity keys are equal, so housemates that share a {@code householdId} but hold
214	     * different telephones have distinct identity keys and are both allowed.
215	     */
216	    public String getIdentityKey() {
217	        return orEmpty(this.telephone) + "|" + orEmpty(this.email) + "|" + orEmpty(this.householdId);
218	    }
219	
220	    private static String orEmpty(String value) {
221	        return value == null ? "" : value;
222	    }
223	
224	    /**
225	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'} where YY is the
226	     * last two digits of the registration date's year (e.g. {@code 'SMI-0007-M26'}). Derived
227	     * from the owner's own fields; absent until both the customer code and registration date
228	     * have been assigned.
229	     */
230	    public String getMembershipNumber() {
231	        if (this.customerCode == null || this.registrationDate == null) {
232	            return null;
233	        }
234	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
235	    }
236	
237	    /**
238	     * The owner's check digit: a single Luhn check digit (0-9) computed over the digits of the
239	     * {@link #getCustomerCode() customer code}. Absent until the customer code has been assigned.
240	     */
241	    public Integer getCheckDigit() {
242	        if (this.customerCode == null) {
243	            return null;
244	        }
245	        return Luhn.checkDigit(this.customerCode);
246	    }
247	
248	    /**
249	     * The owner's tenure in whole days: the number of days elapsed from the
250	     * {@link #getRegistrationDate() registration date} up to today. A freshly registered owner has
251	     * a tenure of zero. Absent until a registration date is present.
252	     */
253	    public Long getTenureDays() {
254	        if (this.registrationDate == null) {
255	            return null;
256	        }
257	        return ChronoUnit.DAYS.between(this.registrationDate, LocalDate.now());
258	    }
259	
260	    /**
261	     * The owner's membership points, a score derived from the owner's own fields: starting from 0,
262	     * the owner earns 2 points when an email address is present, 1 point when this owner has no
263	     * namesakes ({@code namesakeCount} is 0), 2 points for a household of 3 or more members, and 3
264	     * points once the owner's {@link #getTenureDays() tenure} exceeds 365 days.
265	     */
266	    public Integer getMembershipPoints() {
267	        int points = 0;
268	        boolean hasEmail = this.email != null && !this.email.isEmpty();
269	        if (hasEmail) {
270	            points += 2;
271	        }
272	        boolean unique = this.namesakeCount != null && this.namesakeCount == 0;
273	        if (unique) {
274	            points += 1;
275	        }
276	        boolean sharedHousehold = this.householdSize != null && this.householdSize >= 3;
277	        if (sharedHousehold) {
278	            points += 2;
279	        }
280	        Long tenureDays = getTenureDays();
281	        boolean tenured = tenureDays != null && tenureDays > 365;
282	        if (tenured) {
283	            points += 3;
284	        }
285	        return points;
286	    }
287	
288	    /**
289	     * The owner's membership level, a number from 1 to 4 derived from the owner's
290	     * {@link #getMembershipPoints() membership points}: 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and
291	     * 4 for 6 or more.
292	     */
293	    public Integer getMembershipLevel() {
294	        int points = getMembershipPoints();
295	        if (points >= 6) {
296	            return 4;
297	        }
298	        if (points >= 4) {
299	            return 3;
300	        }
301	        if (points >= 2) {
302	            return 2;
303	        }
304	        return 1;
305	    }
306	
307	    /**
308	     * The owner's locality: the REGION segment of the {@link #getCustomerCode() customer code} (the
309	     * region derived from the postcode when the identity was assigned), or {@link Regions#UNKNOWN}
310	     * before a customer code has been assigned.
311	     */
312	    public String getLocality() {
313	        if (this.customerCode == null) {
314	            return Regions.UNKNOWN;
315	        }
316	        int separator = this.customerCode.indexOf('-');
317	        return separator < 0 ? this.customerCode : this.customerCode.substring(0, separator);
318	    }
319	
320	    /**
321	     * The owner's preferred contact channel, derived from the owner's own fields:
322	     * {@code "EMAIL"} when an {@link #getEmail() email} is present, otherwise {@code "PHONE"}.
323	     */
324	    public String getContactPreference() {
325	        boolean hasEmail = this.email != null && !this.email.isEmpty();
326	        return hasEmail ? "EMAIL" : "PHONE";
327	    }
328	
329	    /**
330	     * The owner's age band, derived from the owner's own fields: the whole years between
331	     * {@link #getBirthDate() birth date} and {@link #getRegistrationDate() registration date}
332	     * classified as {@code "MINOR"} (under 18), {@code "ADULT"} (18-64) or {@code "SENIOR"}
333	     * (65 or older). Absent until a birth date and a registration date are both present.
334	     */
335	    public String getAgeBand() {
336	        if (this.birthDate == null || this.registrationDate == null) {
337	            return null;
338	        }
339	        int age = Period.between(this.birthDate, this.registrationDate).getYears();
340	        if (age < 18) {
341	            return "MINOR";
342	        }
343	        return age < 65 ? "ADULT" : "SENIOR";
344	    }
345	
346	    /**
347	     * Resolve the effective registration date before persisting: default it to the server's
348	     * current date when none was supplied, then roll it forward off weekends so a newly
349	     * registered owner always has a business-day registration date. Every value derived from it
350	     * (such as the {@link #getMembershipNumber() membership number}) therefore uses the adjusted
351	     * date.
352	     */
353	    @PrePersist
354	    private void resolveRegistrationDate() {
355	        if (this.registrationDate == null) {
356	            this.registrationDate = LocalDate.now();
357	        }
358	        this.registrationDate = BusinessDay.onOrAfter(this.registrationDate);
359	    }
360	
361	    protected Set<Pet> getPetsInternal() {
362	        if (this.pets == null) {
363	            this.pets = new HashSet<>();
364	        }
365	        return this.pets;
366	    }
367	
368	    protected void setPetsInternal(Set<Pet> pets) {
369	        this.pets = pets;
370	    }
371	
372	    public List<Pet> getPets() {
373	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
374	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
375	        return Collections.unmodifiableList(sortedPets);
376	    }
377	
378	    public void setPets(List<Pet> pets) {
379	        this.pets = new HashSet<>(pets);
380	    }
381	
382	    public void addPet(Pet pet) {
383	        getPetsInternal().add(pet);
384	        pet.setOwner(this);
385	    }
386	
387	    /**
388	     * Return the Pet with the given name, or null if none found for this Owner.
389	     *
390	     * @param name to test
391	     * @return true if pet name is already in use
392	     */
393	    public Pet getPet(String name) {
394	        return getPet(name, false);
395	    }
396	
397	    /**
398	     * Return the Pet with the given name, or null if none found for this Owner.
399	     *
400	     * @param name to test
401	     * @return true if pet name is already in use
402	     */
403	    public Pet getPet(String name, boolean ignoreNew) {
404	        name = name.toLowerCase();
405	        for (Pet pet : getPetsInternal()) {
406	            if (!ignoreNew || !pet.isNew()) {
407	                String compName = pet.getName();
408	                compName = compName.toLowerCase();
409	                if (compName.equals(name)) {
410	                    return pet;
411	                }
412	            }
413	        }
414	        return null;
415	    }
416	
417	    public Pet getPet(Integer petId) {
418	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
419	    }
420	
421	    @Override
422	    public String toString() {
423	        return new ToStringCreator(this)
424	
425	            .append("id", this.getId())
426	            .append("new", this.isNew())
427	            .append("lastName", this.getLastName())
428	            .append("firstName", this.getFirstName())
429	            .append("address", this.address)
430	            .append("city", this.city)
431	            .append("telephone", this.telephone)
432	            .append("email", this.email)
433	            .toString();
434	    }
435	}
